#include "model/arch_qwen.hpp"
#include <chrono>
#include <iomanip>
#include <iostream>
using Clock = std::chrono::steady_clock;
uint64_t vector_hash(const std::vector<float>& values) {
    uint64_t h = 14695981039346656037ull;
    for (float v : values) {
        if (!std::isfinite(v)) throw std::runtime_error("nonfinite output");
        uint32_t bits; std::memcpy(&bits, &v, 4);
        for (int shift=0; shift<32; shift+=8) { h ^= (bits>>shift)&255; h *= 1099511628211ull; }
    }
    return h;
}
#if LLMX_SPANS
void dump(const std::vector<worker_probe::Record>& records) {
    std::cout << '[';
    for (size_t n=0; n<records.size(); ++n) {
        const auto& r=records[n];
        if (n) std::cout << ',';
        std::cout << '[' << r.returned-r.publish;
        for (const auto& p : r.participant) std::cout << ',' << p.enter-r.publish << ',' << p.exit-r.publish;
        std::cout << ']';
    }
    std::cout << ']';
}
#endif
int main(int argc, char** argv) {
    try {
        if (argc != 4) return 2;
        auto weights=gguf::read_gguf(argv[1]);
        auto cpu=std::make_shared<backend::CpuBackend>();
        infer::Model model(weights,cpu);
        model.set_threads(6); model.set_ubatch(128);
        std::ifstream input(argv[2]); std::vector<uint32_t> ids; uint32_t id;
        while(input>>id) ids.push_back(id);
        if(ids.size()!=247 || cpu->threads_available()!=6) return 3;
        std::vector<uint32_t> prompt(ids.begin(),ids.begin()+215);
        uint64_t warmup_hash=0;
        for(int run=0;run<2;++run) {
            model.reset();
#if LLMX_SPANS
            cpu->probe.enabled=run>0; cpu->probe.phase=0;
#endif
            auto start=Clock::now(); auto logits=model.prefill(prompt);
            double pp=std::chrono::duration<double,std::milli>(Clock::now()-start).count();
#if LLMX_SPANS
            cpu->probe.phase=1;
#endif
            start=Clock::now();
            for(size_t i=215;i<ids.size();++i) logits=model.step(ids[i]);
            double tg=std::chrono::duration<double,std::milli>(Clock::now()-start).count();
#if LLMX_SPANS
            cpu->probe.enabled=false;
            if(cpu->probe.overflow) return 4;
#endif
            auto hash=vector_hash(logits);
            if(!run) { warmup_hash=hash; continue; }
            if(hash!=warmup_hash) return 5;
            std::ofstream out(argv[3],std::ios::binary);
            out.exceptions(std::ios::badbit|std::ios::failbit);
            out.write(reinterpret_cast<const char*>(logits.data()),std::streamsize(logits.size()*sizeof(float)));
            out.close();
            std::cout << std::setprecision(12)
                      << "{\"threads\":6,\"pp_ms\":" << pp << ",\"tg_ms\":" << tg
                      << ",\"final_vector_fnv64\":\"" << std::hex << hash << std::dec << '"';
#if LLMX_SPANS
            std::cout << ",\"pp\":"; dump(cpu->probe.records[0]);
            std::cout << ",\"tg\":"; dump(cpu->probe.records[1]);
#endif
            std::cout << "}\n";
        }
    } catch(const std::exception& e) {
        std::cerr << e.what() << '\n'; return 1;
    }
}

