#pragma once
#include <array>
#include <chrono>
#include <cstdint>
#include <vector>
namespace worker_probe {
inline int64_t stamp() noexcept {
    return std::chrono::duration_cast<std::chrono::nanoseconds>(
        std::chrono::steady_clock::now().time_since_epoch()).count();
}
struct alignas(64) Participant { int64_t enter = 0, exit = 0; };
struct Record { int64_t publish = 0, returned = 0; Participant participant[6]; };
struct Trace {
    bool enabled = false, overflow = false;
    unsigned phase = 0;
    std::array<std::vector<Record>, 2> records;
    Trace() { for (auto& r : records) r.reserve(10000); }
    Record* begin() {
        if (!enabled) return nullptr;
        auto& r = records[phase];
        if (r.size() == r.capacity()) { overflow = true; return nullptr; }
        r.emplace_back();
        return &r.back();
    }
};
struct Finish {
    Record* record;
    ~Finish() noexcept { if (record) record->returned = stamp(); }
};
}

