#include "backends/cpu/cpu_backend.hpp"
#include <atomic>
#include <iostream>
int main() {
    backend::CpuBackend cpu;
    cpu.set_threads(6);
    cpu.probe.enabled=true;
    for(int round=0;round<3;++round) {
        std::atomic<int> completed{0};
        bool caught=false;
        try {
            cpu.run_parallel([&](int w) {
                completed.fetch_add(1);
                if(w==0) throw std::runtime_error("caller");
                if(w==1) throw std::runtime_error("worker");
            });
        } catch(const std::runtime_error& e) { caught=std::string(e.what())=="caller"; }
        if(!caught || completed.load()!=6) return 1;
        cpu.run_parallel([&](int) { completed.fetch_add(1); });
        if(completed.load()!=12) return 2;
    }
    cpu.probe.enabled=false;
    if(cpu.probe.records[0].size()!=6 || cpu.probe.overflow) return 3;
    for(const auto& r : cpu.probe.records[0])
        for(const auto& p : r.participant)
            if(p.enter<r.publish || p.exit<p.enter || r.returned<p.exit) return 4;
    std::cout << "instrumented caller priority, worker completion, exception propagation and pool reuse pass\n";
}

